import os

import joblib
import streamlit as st


MODEL_PATH = "models/ai_text_detector.joblib"


st.set_page_config(
    page_title="AI Text Detector",
    page_icon="🤖",
    layout="centered"
)


@st.cache_resource
def load_model():
    return joblib.load(MODEL_PATH)


st.title("AI-Generated Text Detector")

st.write(
    "Enter a piece of text below to estimate whether it was "
    "written by a human or generated by an AI model."
)

st.info(
    "This detector uses TF-IDF features and Logistic Regression "
    "trained on the HC3 Human-ChatGPT Comparison Corpus."
)


if not os.path.exists(MODEL_PATH):
    st.error(
        "Model not found. Run `python src/train_model.py` first."
    )
    st.stop()


model = load_model()

text = st.text_area(
    "Enter text",
    height=250,
    placeholder="Paste an article, paragraph, answer, or other text here..."
)


if st.button("Analyze Text"):

    if not text.strip():
        st.warning("Please enter some text first.")

    else:
        prediction = model.predict([text])[0]
        probabilities = model.predict_proba([text])[0]

        human_probability = probabilities[0]
        ai_probability = probabilities[1]

        st.subheader("Prediction")

        if prediction == 1:
            st.error("🤖 Likely AI-generated")
            confidence = ai_probability
        else:
            st.success("👤 Likely Human-written")
            confidence = human_probability

        st.metric(
            "Model Confidence",
            f"{confidence * 100:.2f}%"
        )

        st.write("### Probability Breakdown")

        col1, col2 = st.columns(2)

        with col1:
            st.metric(
                "Human",
                f"{human_probability * 100:.2f}%"
            )

        with col2:
            st.metric(
                "AI-generated",
                f"{ai_probability * 100:.2f}%"
            )

        st.progress(float(ai_probability))

        st.caption(
            "This probability is the model's estimated confidence, "
            "not definitive proof of authorship."
        )